<?php $page_title='Dashboard Dosen';require_once __DIR__.'/../includes/header.php';require_login(['dosen']);$pdo=db();$id=lecturer_id();$q=$pdo->prepare('SELECT COUNT(*) FROM kelas WHERE id_dosen=?');$q->execute([$id]);$courses=$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(DISTINCT k.id_mahasiswa) FROM krs k JOIN kelas kl ON kl.id=k.id_kelas WHERE kl.id_dosen=?');$q->execute([$id]);$students=$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM nilai n JOIN krs k ON k.id=n.id_krs JOIN kelas kl ON kl.id=k.id_kelas WHERE kl.id_dosen=?');$q->execute([$id]);$grades=$q->fetchColumn();?><h3 class="mb-4">Dashboard Dosen</h3><div class="row g-3"><?php foreach([['Mata Kuliah',$courses,'bi-book'],['Mahasiswa',$students,'bi-people'],['Nilai Diinput',$grades,'bi-award']] as [$n,$v,$i]):?><div class="col-md-4"><div class="card p-4"><i class="bi <?=$i?> text-primary fs-3"></i><div class="text-secondary mt-2"><?=$n?></div><div class="display-6 fw-bold"><?=$v?></div></div></div><?php endforeach?></div><?php require_once __DIR__.'/../includes/footer.php';?>
